    },
    "text": "Display_name must be unique across members.users to prevent impersonation.",
    "assertion": "forall INSERT/UPDATE members.users: UNIQUE(display_name) constraint enforced",
    "covers": "SG-005",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

